const excerpt$1a = '<h1 id="inertialsensor" tabindex="-1">Inertialsensor</h1>\n<p><img src="/mks-welcome/mks/parts/mks-Adafruit-Adafruit_ICM-20948/12_intertialsensor_rz.png" alt="Inertialsensor"></p>\n<h2 id="beschreibung" tabindex="-1">Beschreibung</h2>\n<p>Der TDK InvenSense ICM-20948 ist ein sogenannter neunachsiger Inertialsensor.\nInertialsensoren kombinieren mehrere Sensortypen, um jegliche dreidimensionale Bewegung (Verschiebungen und Neigungen in allen Raumrichtungen) zu bestimmen.</p>\n';
