const excerpt$18 = '<h1 id="arduino-uno" tabindex="-1">Arduino UNO</h1>\n<p><img src="/mks-welcome/mks/parts/mks-Arduino-UNO_R3/1_arduino.png" alt="Arduino UNO"></p>\n<h2 id="beschreibung" tabindex="-1">Beschreibung</h2>\n<p>Der Arduino UNO ist ein Mikrocontroller, der es ermöglicht, prinzipiell jegliche Art von technischen Vorgängen automatisiert miteinander zu koordinieren.\nDafür besitzt der Mikrocontroller viele Ein- und Ausgänge (Inputs und Outputs).\nDiese sind elektrische Anschlüsse, an die verschiedene technische Komponenten, wie Sensoren oder auch Aktoren (Motoren, Leuchten etc.), angeschlossen werden können.\nWird der Mikrocontroller entsprechend programmiert, können diese Komponenten logisch miteinander verknüpft werden.\nDadurch können die Komponenten gemeinsam eine technische Aufgabe erfüllen.</p>\n';
