        createStaticVNode('<h1 id="makey-makey" tabindex="-1">Makey-Makey</h1><p><img src="/mks-welcome/mks/parts/mks-JoyLabz-MakeyMakey/55_makeymakey.png" alt="Makey-Makey"></p><h2 id="beschreibung" tabindex="-1">Beschreibung</h2><p>Mit den Makey-Makey-Modulen lassen sich viele Alltagsgegenstände in Eingabegeräte verwandeln. Leitfähige Gegenstände wie Alufolie oder Früchte können einfach mit Krokodilklemmen an das Makey-Makey-Modul angeschlossen werden. Ist man zusätzlich selbst ebenfalls mit dem Makey-Makey verbunden, erkennt das Modul eine Berührung der leitfähigen Gegenstände. Das Makey-Makey wird schließlich mit USB an einen PC angeschlossen und damit können simple Spiele oder Anwendungen gesteuert werden.</p><p>Dadurch lassen sich beispielsweise Früchte oder auch Treppenstufen zu Klaviertasten verwandeln.</p><p>Alle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf der offiziellen Produktseite von Makey Makey zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen meist nur mit der Eingabe der genauen Komponenten-Bezeichnungen entsprechende Projektbeispiele und Tutorials.</p><h2 id="wichtige-links-f%C3%BCr-die-ersten-schritte%3A" tabindex="-1">Wichtige Links für die ersten Schritte:</h2><ul><li><a href="https://www.makeymakey.com/">Makey-Makey Produktseite</a></li></ul>', 8)
