        createStaticVNode('<h1 id="kamera" tabindex="-1">Kamera</h1><p><img src="/mks-welcome/mks/parts/mks-Raspberry_Pi-camera_module_v2/37_kamera.png" alt="Kamera"></p><h2 id="beschreibung" tabindex="-1">Beschreibung</h2><p>Das Kameramodul kann wie eine handelsübliche Webcam eingesetzt werden. Die Kamera ist speziell für den Raspberry Pi entwickelt und kann einfach über den CSI-Steckplatz (Camera Serial Interface) angeschlossen werden. Das Modul ist mit einem hochwertigen Bildsensor von Sony ausgestattet, der eine Bildauflösung bis 8 Megapixel liefert. Daneben können Videoaufnahmen erstellt werden bei 1080p mit 30fps, bei 720p mit 60fps und bei 640x480 Pixeln mit bis zu 90fps. Eine optimale Handhabung wird durch automatische Steuerfunktionen für Belichtung, Lichtstärkeerkennung und Weißabgleich sichergestellt.</p><p>Ideale Anwendungsbereiche des Moduls sind unter anderem Überwachungskameras, sowie Haus- und Wildtierbeobachtungen. Für dunklere Lichtverhältnisse empfiehlt sich die NoIR-Version der Raspberry Pi Camera V2.</p><p>Alle weiteren Hintergrundinformationen, sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken findet man über alle gängigen Suchmaschinen durch die Eingabe der genauen Komponentenbezeichnungen.</p><h2 id="wichtige-links-f%C3%BCr-die-ersten-schritte%3A" tabindex="-1">Wichtige Links für die ersten Schritte:</h2><ul><li><a href="https://projects.raspberrypi.org/en/projects/getting-started-with-picamera">Raspberry Pi Projects - Picamera</a></li></ul><h2 id="projektbeispiele%3A" tabindex="-1">Projektbeispiele:</h2><ul><li><a href="https://www.dietle.de/bau-einer-ueberwachungskamera-mit-raspberry-pi/">Dietle - Überwachungskamera</a></li></ul><h2 id="weiterf%C3%BChrende-hintergrundinformationen%3A" tabindex="-1">Weiterführende Hintergrundinformationen:</h2><ul><li><a href="https://de.wikipedia.org/wiki/Raspberry_Pi">Raspberry Pi - Wikipedia Artikel</a> <a href="https://de.wikipedia.org/wiki/Raspberry_Pi">(Camera</a> <a href="https://de.wikipedia.org/wiki/Raspberry_Pi">Serial Interface)</a></li></ul>', 12)
