const excerpt$11 = '<h1 id="rfid-leser" tabindex="-1">RFID-Leser</h1>\n<p><img src="/mks-welcome/mks/parts/mks-SeeedStudio-Grove_125KHz_RFID_Reader_v1.0/52_rfid_leser.png" alt="RFID-Leser"></p>\n<h2 id="beschreibung" tabindex="-1">Beschreibung</h2>\n<p>RFID bezeichnet ein Sender-Empfänger-System, das vor allem zur eindeutigen Identifizierung von Objekten, Einkaufswaren oder auch Lebewesen eingesetzt wird. Der RFID-Transponder besitzt eine eindeutige Identifikationsnummer. Das Lesegerät liest diese aus, sobald der Transponder in unmittelbarer Nähe ist. Der Transponder benötigt dabei keine Stromversorgung, da das Auslesegerät ihn kontaktlost mit Energie versorgt.</p>\n';
