        _cache[8] || (_cache[8] = createStaticVNode('<p>Auf der Platine können schließlich zwei verschiedene Verstärkungsfaktoren ausgewählt werden: 3 oder 10. Die Ausgangsspannung wird folgendermaßen berechnet:</p><p><img src="images/verstaerker_formel_texte_online-1-300x67.png" alt=""></p><p>Mit dem Spannungsteiler kann z.B. der ungefähre Füllstand eines Li-Po-Akkus ermittelt werden. Ein Li-Po-Akku besteht normalerweise aus vielen einzelnen Zellen, die jeweils eine Nennspannung von 3.7V besitzen. Daher gibt es Li-Po-Akkus mit 3.7V, 7.4V, 11.1V, 14.8V, 18.5V etc. Jede einzelne Li-Po-Zelle eines Akkus hat im vollgeladenen Zustand eine Spannung von ca. 4.2V. Eine Li-Po-Zelle eines Akkus sollte nicht unter 3.4V fallen. Über die Spannungsmessung kann schließlich der Füllstand grob ermittelt werden.</p><p>ACHTUNG: Hiermit können keine Spannungsquellen oder Stromversorgungen umgewandelt werden. Es dient lediglich der Messung oder Erfassung von Spannungen.</p><p>Alle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf dem offiziellen Wiki (bisher nur in englischer Sprache) von Seeed Studio zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen meist nur mit der Eingabe der genauen Komponentenbezeichnung entsprechende Projektbeispiele und Tutorials.</p><h2 id="wichtige-links-f%C3%BCr-die-ersten-schritte%3A" tabindex="-1">Wichtige Links für die ersten Schritte:</h2><ul><li><a href="http://wiki.seeedstudio.com/Grove-Voltage_Divider/">Seeed Studio Wiki</a> <a href="http://wiki.seeedstudio.com/Grove-Voltage_Divider/">- Spannungsteiler</a></li></ul><h2 id="weiterf%C3%BChrende-hintergrundinformationen%3A" tabindex="-1">Weiterführende Hintergrundinformationen:</h2><ul><li><a href="https://de.wikipedia.org/wiki/Lithium-Polymer-Akkumulator">Lithium Polymer Akkumulatoren - Wikipedia Artikel</a></li></ul>', 9))
