    const frontmatter = { "title": "SenseBox Shield (Arduino)", "date": "2018-10-01T15:02:45.000Z", "tags": ["shield"], "coverImage": "68_sensebox_shield_arduino.png", "material_number": "68", "material_type": "shield", "material_short_descr": "SenseBox – Home Shield", "manufacture": "Reedu GmbH & Co. KG", "manufacture_url": "https://sensebox.de/", "repo_name": "mks-SenseBox-Shield", "clone_url": "https://github.com/Make-Your-School/mks-SenseBox-Shield.git", "repo_prefix": "mks", "repo_part": "Shield", "embedded_example_file": "examples/Shield_minimal/Shield_minimal.ino" };
