        createStaticVNode('<h1 id="peristaltikpumpe" tabindex="-1">Peristaltikpumpe</h1><p><img src="/mks-welcome/mks/parts/mks-generic-PeristalticPump/43_peristaltikpumpe.png" alt="Peristaltikpumpe"></p><h2 id="beschreibung" tabindex="-1">Beschreibung</h2><p>Die Peristaltikpumpe bringt durch Kneten eines Silikonschlauchs die darin befindliche Flüssigkeit in Bewegung und drückt diese so durch den Schlauch hindurch. Dabei kommen die mechanischen Bauteile der Pumpe nicht mit der Flüssigkeit in Kontakt und so lässt sie sich auch für Getränke oder andere flüssige Nahrungsmittel oder sterile Flüssigkeiten nutzen. Da die Pumpe durch einen Gleichstrommotor angetrieben wird, wird sie auch wie dieser angeschlossen. Die Steuerung erfolgt über ein einfaches Relais, einen Transistor, einen manuellen Schalter oder einen Motortreiber, der als fertiges Modul zwischen Mikrocontroller und Gleichstrommotor geschaltet wird.</p><p>Die Peristaltikpumpe kann zur Bewässerung von Pflanzen oder zum Aufbau eines Wasserspenders eingesetzt werden.</p><p>Alle weiteren Hintergrundinformationen, sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken findet man über alle gängigen Suchmaschinen meist nur mit der Eingabe der genauen Komponentenbezeichnungen. Das wichtige Stichwort lautet hier „DC Motor“ oder „Gleichstrommotor“.</p><h2 id="wichtige-links-f%C3%BCr-die-ersten-schritte%3A" tabindex="-1">Wichtige Links für die ersten Schritte:</h2><ul><li><a href="https://www.adafruit.com/product/1150">Adafruit Wasserpumpe</a></li></ul><h2 id="weiterf%C3%BChrende-hintergrundinformationen%3A" tabindex="-1">Weiterführende Hintergrundinformationen:</h2><ul><li><a href="https://de.wikipedia.org/wiki/Allzweckeingabe/-ausgabe">GPIO - Wikipedia Artikel</a></li><li><a href="https://de.wikipedia.org/wiki/Schlauchpumpe">Peristaltikpumpe - Wikipedia Artikel</a></li></ul>', 10)
