const readme$v = '---\ntitle: "Berührungssensor"\ndate: "2018-10-02T07:02:32.000Z"\ntags: \n  - "sensor"\ncoverImage: "57_beruehrungssensor_qtouch.png"\nmaterial_number: "57"\nmaterial_type: "input"\nmaterial_short_descr: "Seeed Studio Grove – QTouch Sensor"\nmanufacture: "Seeed Studio"\nmanufacture_url: "https://www.seeedstudio.com/"\nrepo_name: "mks-SeeedStudio-Grove_Q_Touch_Sensor"\nrepo_prefix: "mks"\nrepo_manufacture: "SeeedStudio"\nrepo_part: "Grove_Q_Touch_Sensor"\nproduct_url: "http://wiki.seeedstudio.com/Grove-Q_Touch_Sensor/"\nclone_url: "https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Q_Touch_Sensor.git"\nembedded_example_file: "examples/Grove_Q_Touch_Sensor_minimal/Grove_Q_Touch_Sensor_minimal.ino"\n---\n\n\n# Berührungssensor\n\n![Berührungssensor](./57_beruehrungssensor_qtouch.png)\n\n## Beschreibung\nDer Berührungssensor QTouch erkennt, sobald ein an den Sensor angeschlossener Gegenstand berührt wird. So lässt sich beispielsweise eine Banane mit dem Sensor verbinden. Sobald die Banane berührt wird, übermittelt dies der Sensor an den Mikrocontroller. Es können gleichzeitig bis zu sieben Berührungsobjekte an das Modul angeschlossen werden. Der Berührungssensor lässt sich direkt oder mithilfe des Grove Shields an einen Arduino oder Raspberry Pi über die serielle Schnittstelle I2Cangeschlossen.\n\nDas Modul kommt beispielsweise beim Bau einer Leuchte zum Einsatz, die durch Berührung des Gehäuses an- oder ausgeschaltet wird.\n\nAlle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf dem offiziellen Wiki (bisher nur in englischer Sprache) von Seeed Studio zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen meist nur mit der Eingabe der genauen Komponenten-Bezeichnungen entsprechende Projektbeispiele und Tutorials.\n\n \n\n\n<!-- currently no valid example available...\n## Beispiel\n\nschau dir das Minimal-Beispiel an:\n\n```c++:public/mks/parts/mks-SeeedStudio-Grove_Q_Touch_Sensor/examples/Grove_Q_Touch_Sensor_minimal/Grove_Q_Touch_Sensor_minimal.ino\n// look in the linked file.\n```\n-->\n\n<!-- infolist -->\n\n## Wichtige Links für die ersten Schritte:\n\n- [Seeed Studio Wiki](http://wiki.seeedstudio.com/Grove-Q_Touch_Sensor/) [- QTouch Berührungssensor](http://wiki.seeedstudio.com/Grove-Q_Touch_Sensor/)\n\n## Weiterführende Hintergrundinformationen:\n\n- [I2C - Wikipedia Artikel](https://de.wikipedia.org/wiki/I%C2%B2C)\n- [SPI - Wikipedia Artikel](https://de.wikipedia.org/wiki/Serial_Peripheral_Interface)\n- [UART - Wikipedia Artikel](https://de.wikipedia.org/wiki/Universal_Asynchronous_Receiver_Transmitter)\n- [GitHub-Repository: Berührungssensor QTouch](https://github.com/MakeYourSchool/57-Beruehrungssensor-QTouch)\n\n';
