const readme$l = '---\ntitle: "WiFi-Modul"\ndate: "2018-10-01T14:44:57.000Z"\ntags: \n  - "sensor"\ncoverImage: "54_wifi-modul.png"\nmaterial_number: "54"\nmaterial_type: "input"\nmaterial_short_descr: "Seeed Studio Grove – UART Wi-Fi"\nmanufacture: "Seeed Studio"\nmanufacture_url: "https://www.seeedstudio.com/"\nrepo_name: "mks-SeeedStudio-Grove_UART_Wifi"\nproduct_url: "http://wiki.seeedstudio.com/Grove-UART_Wifi/"\nclone_url: "https://github.com/Make-Your-School/mks-SeeedStudio-Grove_UART_Wifi.git"\nrepo_prefix: "mks"\nrepo_part: "Grove_UART_Wifi"\nembedded_example_file: "examples/Grove_UART_Wifi_minimal/Grove_UART_Wifi_minimal.ino"\n---\n\n\n# WiFi-Modul\n\n![WiFi-Modul](./54_wifi-modul.png)\n\n## Beschreibung\nDas WiFi-Modul ermöglicht es Informationen, Befehle und Daten kabellos zwischen mehreren Endgeräten oder Mikrocontrollern innerhalb eines Netzwerkes zu übertragen. So lassen sich beispielsweise Sensordaten von einem Arduino in ein lokales Netzwerk stellen und damit an PCs oder Smartphones übertragen oder sogar über einen Router ins Internet stellen und von überall auf der Welt abrufen. Das Modul kann über bestimmte Befehle programmiert werden. So kann unter anderem das Modul selbst einen Zugangspunkt für andere Netzwerk-Clients darstellen oder sich in ein bestehendes WLAN einwählen. Das Modul kann direkt oder mithilfe des Grove Shields an einen Arduino oder Raspberry Pi über die serielle Schnittstelle UART angeschlossen werden.\n\nDas WiFi-Modul ist eines der Grundsteine für alle vernetzte Projekte und Internet-of-Things-Projekte.\n\nAlle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf dem offiziellen Wiki (bisher nur in englischer Sprache) von Seeed Studio zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen meist nur mit der Eingabe der genauen Komponenten-Bezeichnungen entsprechende Projektbeispiele und Tutorials.\n\nDie genaue Bezeichnung des Moduls, die bei der Suche von Beschreibungen und Anleitungen wichtig sein kann, lautet ESP8266.\n\n\n<!-- currently no valid example available...\n## Beispiel\n\nschau dir das Minimal-Beispiel an:\n\n```c++:public/mks/parts/mks-SeeedStudio-Grove_UART_Wifi/examples/Grove_UART_Wifi_minimal/Grove_UART_Wifi_minimal.ino\n// look in the linked file.\n```\n-->\n\n<!-- infolist -->\n\n## Wichtige Links für die ersten Schritte:\n\n- [Seeed Studio Wiki](http://wiki.seeedstudio.com/Grove-UART_Wifi/) [- WiFi](http://wiki.seeedstudio.com/Grove-UART_Wifi/)\n- [Seeed Studio Youtube Kanal – Wirelessproducts comparison](https://www.youtube.com/watch?v=5hg0lllDTLk)\n- [nl – Befehlsliste](https://nurdspace.nl/ESP8266)\n- [GitHub – esp8266 Wiki](https://github.com/esp8266/esp8266-wiki/wiki)\n- [ESP8266 Community Forum](https://www.esp8266.com/viewforum.php?f=25)\n\n## Projektbeispiele:\n\n- [msxfaq - ESP8266 Beispiel Projekte](https://www.msxfaq.de/sonst/bastelbude/esp8266/esp8266-projekte.htm)\n- [GitHub – Demo Sketch](https://github.com/allthingstalk/arduino-UART-client/blob/master/libraries/ATT_IOT_UART/examples/genuino101/led/led.ino)\n- [Instructables – Getting Started with ESP8285](https://www.instructables.com/id/How-to-Get-Started-With-ESP8285-Module-/)\n\n## Weiterführende Hintergrundinformationen:\n\n- [I2C - Wikipedia Artikel](https://de.wikipedia.org/wiki/I%C2%B2C)\n- [SPI - Wikipedia Artikel](https://de.wikipedia.org/wiki/Serial_Peripheral_Interface)\n- [UART - Wikipedia Artikel](https://de.wikipedia.org/wiki/Universal_Asynchronous_Receiver_Transmitter)\n- [WiFi - Wikipedia Artikel](https://de.wikipedia.org/wiki/Wi-Fi)\n- [Internet der Dinge](https://de.wikipedia.org/wiki/Internet_der_Dinge) [(IoT)](https://de.wikipedia.org/wiki/Internet_der_Dinge) [- Wikipedia Artikel](https://de.wikipedia.org/wiki/Internet_der_Dinge)\n- [Access Point - Wikipedia Artikel](https://de.wikipedia.org/wiki/Wireless_Access_Point)\n- [GitHub-Repository: WiFi-Modul](https://github.com/MakeYourSchool/54-Wifi-Modul)\n\n';
const __vite_glob_3_53 = /* @__PURE__ */ Object.freeze(/* @__PURE__ */ Object.defineProperty({
  __proto__: null,
  default: readme$l
}, Symbol.toStringTag, { value: "Module" }));
const readme$k = '---\ntitle: "UV-Lichtsensor"\ndate: "2018-10-01T12:49:38.000Z"\ntags: \n  - "sensor"\ncoverImage: "mys_mk_6.png"\nmaterial_number: "6"\nmaterial_type: "input"\nmaterial_short_descr: "Seeed Studio Grove - UV Sensor"\nmanufacture: "Seeed Studio"\nmanufacture_url: "https://www.seeedstudio.com/"\nrepo_name: "mks-SeeedStudio-Grove_UV_Sensor"\nproduct_url: "https://wiki.seeedstudio.com/Grove-UV_Sensor/"\nclone_url: "https://github.com/Make-Your-School/mks-SeeedStudio-Grove_UV_Sensor.git"\nrepo_prefix: "mks"\nrepo_part: "Grove_UV_Sensor"\nembedded_example_file: "examples/Grove_UV_Sensor_minimal/Grove_UV_Sensor_minimal.ino"\n---\n\n\n# UV-Lichtsensor\n\n![UV-Lichtsensor](./mys_mk_6.png)\n\n## Beschreibung\nDer UV-Lichtsensor erfasst die Intensität der auf ihn einwirkenden Ultraviolettstrahlung (kurz: UV). UV-Strahlung ist eine elektromagnetische Strahlung mit einer Wellenlänge zwischen 10 nm (Nanometer) und 380 nm. Die Wellenlänge ist damit länger als die von Röntgenstrahlung und kürzer als die von sichtbarem, violettem Licht. UV-Strahlung ist für das menschliche Auge unsichtbar und ist bspw. im kurzwelligen Anteil der Sonnenstrahlung enthalten.\n\nDie Sensibilität des Sensors ist am höchsten bei einer Strahlung mit einer Wellenlänge zwischen 200 nm und 400 nm. Dadurch erfasst der Sensor sowohl UV-Strahlung als auch einen geringen Anteil des sichtbaren violetten Lichts.\n\nDer Sensor kann direkt oder mithilfe des Grove Shields an einen Arduino oder Raspberry Pi angeschlossen werden. Der Sensor wird dabei an einen analogen Eingang angeschlossen.\n\nDas Modul wird beispielsweise in einer Messstation für Umweltdaten, wie Feinstaub, Lautstärke, Luftfeuchtigkeit, Temperatur und UV-Strahlung eingesetzt.\n\nAlle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf dem offiziellen Wiki (bisher nur in englischer Sprache) von Seeed Studio zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen durch die Eingabe der genauen Komponentenbezeichnung entsprechende Projektbeispiele und Tutorials.\n\n\n## Beispiel\n\nschau dir das Minimal-Beispiel an:\n\n```c++:public/mks/parts/mks-SeeedStudio-Grove_UV_Sensor/examples/Grove_UV_Sensor_minimal/Grove_UV_Sensor_minimal.ino\n// look in the linked file.\n```\n\n<!-- infolist -->\n\n## Wichtige Links für die ersten Schritte:\n\n- [Seeed Studio Wiki – UV Sensor](https://wiki.seeedstudio.com/Grove-UV_Sensor/) \n\n## Weiterführende Hintergrundinformationen:\n\n- [UV-Strahlung – Wikipedia Artikel](https://de.wikipedia.org/wiki/Ultraviolettstrahlung)\n- [Spektrum Elektromagnetische Strahlung – Wikipedia Artikel](https://de.wikipedia.org/wiki/Elektromagnetisches_Spektrum)\n- [GitHub-Repository: UV-Lichtsensor](https://github.com/MakeYourSchool/6-UV-Lichtsensor)\n\n\n\n';
const __vite_glob_3_54 = /* @__PURE__ */ Object.freeze(/* @__PURE__ */ Object.defineProperty({
  __proto__: null,
  default: readme$k
}, Symbol.toStringTag, { value: "Module" }));
const readme$j = '---\ntitle: "Ultraschall-Entfernungssensor"\ndate: "2018-10-01T13:31:08.000Z"\ntags: \n  - "sensor"\ncoverImage: "17_ultraschallentfernungssensor.png"\nmaterial_number: "17"\nmaterial_type: "input"\nmaterial_short_descr: "Seeed Studio Grove – Ultrasonic Ranger"\nmanufacture: "Seeed Studio"\nmanufacture_url: "https://www.seeedstudio.com/"\nrepo_name: "mks-SeeedStudio-Grove_Ultrasonic_Ranger"\nrepo_prefix: "mks"\nrepo_manufacture: "SeeedStudio"\nrepo_part: "Grove_Ultrasonic_Ranger"\nproduct_url: "https://wiki.seeedstudio.com/Grove-Ultrasonic_Ranger/"\nclone_url: "https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Ultrasonic_Ranger.git"\nembedded_example_file: "examples/Grove_Ultrasonic_Ranger_minimal/Grove_Ultrasonic_Ranger_minimal.ino"\n---\n\n\n# Ultraschall-Entfernungssensor\n\n![Ultraschall-Entfernungssensor](./17_ultraschallentfernungssensor.png)\n\n## Beschreibung\nDer Ultraschall-Entfernungssensor misst die Entfernung zwischen sich und einem vor ihm positionierten Gegenstand. Der Sensor strahlt eigene Ultraschall-Signale aus und analysiert das vom Objekt reflektierte Echo. So lassen sich Entfernungen zwischen 2cm und 350cm erfassen. Die Genauigkeit liegt hierbei bei  1cm.\n\nDer Sensor kann direkt oder mithilfe des Grove Shields an einen Arduino oder Raspberry Pi angeschlossen werden. Der Sensor kommuniziert über ein digitales Signal.\n\nAlle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken findet man über alle gängigen Suchmaschinen durch die Eingabe der genauen Komponentenbezeichnungen. Diese ist normalerweise direkt auf der Platine des Sensors markiert. Im Folgenden sind zwei Anleitungen zu den zwei gängigsten Sensortypen zusammengefasst.\n\n\n## Beispiel\n\nschau dir das Minimal-Beispiel an:\n\n```c++:public/mks/parts/mks-SeeedStudio-Grove_Ultrasonic_Ranger/examples/Grove_Ultrasonic_Ranger_minimal/Grove_Ultrasonic_Ranger_minimal.ino\n// look in the linked file.\n```\n\n<!-- infolist -->\n\n@[youtube](https://www.youtube.com/watch?v=J8BHAVSdJe0&t=16s)\n\n \n\n## Wichtige Hinweise:\n\n- Es gibt zwei Arten von Ultraschall-Entfernungssensoren, die unterschiedlich verwendet werden müssen. Je nach Sensortyp kann der Anschluss und die Verwendung des Sensors leicht variieren.\n- Der allgemeine Ultraschall-Entfernungssensor bezieht sich auf den Sensortyp HC-SR04. Man erkennt diesen an der roten Farbe und den vier folgenden Anschlüssen: VCC, Trig, Echo und GND.\n- Der Grove Ultraschall-Entfernungssensor bezieht sich nur auf den speziellen Sensor von der Firma Seeed Studio. Man erkennt diesen an der blauen Platine und am Steckplatz mit den drei belegten Anschlüssen: GND, VCC und SIG. Der vierte Anschluss ist mit „NC“ beschriftet und bedeutet „not connected“ (deutsch: nicht belegt).\n- Im Rahmen von _Make-Your-School-_Hackdays wird der im Bild gezeigte Grove Sensor von Seeed eingesetzt. Ihr findet die entsprechende Anleitung unter dem Link bei "Wichtige Links für die ersten Schritte". Für alle anderen Ultraschall-Entfernungssensoren (HC-SR04) könnt ihr die Projektbeispiele "Instructables - Arduino Ultrasonic Sensor" und "Arduino Project Hub - Blindenstock" als Einführung nutzen.\n\n## Wichtige Links für die ersten Schritte:\n\n- [Seeed Studio Wiki - Ultraschall Entfernungssensor](http://wiki.seeedstudio.com/Grove-Ultrasonic_Ranger/)\n\n## Projektbeispiele:\n\n- [Ultraschall-Entfernungssensor mit einem LCD-Bildschirm verbinden](https://simple-circuit.com/arduino-grove-ultrasonic-ranger-distance-meter-lcd/) \n- [Instructables – Arduino Ultrasonic Sensor](https://www.instructables.com/id/Arduino-Ultrasonic-Sensor/)\n- [Arduino Project Hub – Blindenstock](https://create.arduino.cc/projecthub/hadi1234/arduino-blind-stick-19d865?ref=tag&ref_id=ultrasonic&offset=19)\n\n## Weiterführende Hintergrundinformationen:\n\n- [GPIO - Wikipedia Artikel](https://de.wikipedia.org/wiki/Allzweckeingabe/-ausgabe)\n- [Schallgeschwindigkeit – Wikipedia Artikel](https://de.wikipedia.org/wiki/Schallgeschwindigkeit)\n- [GitHub-Repository: Ultraschall-Entfernungssensor](https://github.com/MakeYourSchool/17-Ultraschall-Entfernungssensor)\n\n\n\n';
const __vite_glob_3_55 = /* @__PURE__ */ Object.freeze(/* @__PURE__ */ Object.defineProperty({
  __proto__: null,
  default: readme$j
}, Symbol.toStringTag, { value: "Module" }));
const readme$i = '---\ntitle: "Vibrationsmotor"\ndate: "2018-10-01T14:26:43.000Z"\ntags: \n  - "output"\ncoverImage: "47_vibratonsmotor.png"\nmaterial_number: "47"\nmaterial_type: "output"\nmaterial_short_descr: "Seeed Studio Grove – Vibration Motor"\nmanufacture: "Seeed Studio"\nmanufacture_url: "https://www.seeedstudio.com/"\nrepo_name: "mks-SeeedStudio-Grove_Vibration_Motor_v1.2"\nproduct_url: "https://wiki.seeedstudio.com/Grove-Vibration_Motor"\nclone_url: "https://github.com/Make-Your-School/mks-SeeedStudio-Grove_Vibration_Motor_v1.2.git"\nrepo_prefix: "mks"\nrepo_part: "Grove_Vibration_Motor_v1.2"\nembedded_example_file: "examples/Grove_Vibration_Motor_v1.2_minimal/Grove_Vibration_Motor_v1.2_minimal.ino"\n---\n\n\n# Vibrationsmotor\n\n![Vibrationsmotor](./47_vibratonsmotor.png)\n\n## Beschreibung\nDer Miniatur-Vibrationsmotor erzeugt trotz des kleinen Bauraums eine relativ starke Vibration. Dadurch kann für diverse Anwendungen beispielsweise ein haptisches Feedback bewirkt werden. Der Motor lässt sich direkt oder mithilfe des Grove Shields an einen Arduino oder Raspberry Pi anschließen. Mit einem einfachen digitalen HIGH-Signalvibriert der Motor dann ähnlich wie ein stumm geschaltetes Smartphone.\n\nAlle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf dem offiziellen Wiki (bisher nur in englischer Sprache) von Seeed Studio zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen meist nur mit der Eingabe der genauen Komponenten-Bezeichnungen entsprechende Projektbeispiele und Tutorials.\n\n\n## Beispiel\n\nschau dir das Minimal-Beispiel an:\n\n```c++:public/mks/parts/mks-SeeedStudio-Grove_Vibration_Motor_v1.2/examples/Grove_Vibration_Motor_v1.2_minimal/Grove_Vibration_Motor_v1.2_minimal.ino\n// look in the linked file.\n```\n\n<!-- infolist -->\n\n \n\n## Wichtige Links für die ersten Schritte:\n\n- [Seeed Studio Wiki](http://wiki.seeedstudio.com/Grove-Vibration_Motor/) [- Vibrationsmotor](http://wiki.seeedstudio.com/Grove-Vibration_Motor/)\n\n## Projektbeispiele:\n\n- [Arduino-Tutorial - Direkte Motoransteuerung](https://www.arduino-tutorial.de/motorsteuerung-direkt-per-arduino/)\n\n## Weiterführende Hintergrundinformationen:\n\n- [GPIO - Wikipedia Artikel](https://de.wikipedia.org/wiki/Allzweckeingabe/-ausgabe)\n- [GitHub-Repository: Vibrationsmotor](https://github.com/MakeYourSchool/47-Vibrationsmotor)\n\n\n\n';
