const readme$f = '---\ntitle: "SD-Karten-Shield"\ndate: "2018-10-01T15:19:28.000Z"\ntags: \n  - "shield"\ncoverImage: "73_sd-karten_shield.png"\nmaterial_number: "73"\nmaterial_type: "shield"\nmaterial_short_descr: "Seeed Studio Grove – SD Card Shield V4"\nmanufacture: "Seeed Studio"\nmanufacture_url: "https://www.seeedstudio.com/"\nrepo_name: "mks-SeeedStudio-SD_Card_shield_V4.0"\nproduct_url: "http://wiki.seeedstudio.com/SD_Card_shield_V4.0/"\nclone_url: "https://github.com/Make-Your-School/mks-SeeedStudio-SD_Card_shield_V4.0.git"\nrepo_prefix: "mks"\nrepo_part: "SD_Card_shield_V4.0"\nembedded_example_file: "examples/SD_Card_shield_V4.0_minimal/SD_Card_shield_V4.0_minimal.ino"\n---\n\n\n# SD-Karten-Shield\n\n![SD-Karten-Shield](./73_sd-karten_shield.png)\n\n## Beschreibung\nDas SD-Karten-Shield ist eine Erweiterungsplatine für Arduino-ähnliche Mikrocontroller. Diese Erweiterungsplatinen werden im Allgemeinen als „Shield“ bezeichnet und werden einfach auf den entsprechenden Controller oder Einplatinencomputer gesteckt. Diese vereinfachen das Anschließen von speziellen Komponenten enorm.\n\nDiese spezielle Ausführung erweitert einen Arduino um einen SD-Karten-Anschluss. Dadurch kann der Mikrocontroller Daten oder Informationen auf einer SD-Karte zwischenspeichern oder von dieser auslesen. Dabei können sowohl normale SD-Karten als auch Mikro-SD-Karten (mittels beiliegendem Adapter) verwendet werden.\n\nDas Shield wird auf den Arduino gesteckt und ist damit mit allen relevanten Anschlüssen des Controllers verbunden. Es nutzt die serielle Schnittstelle SPI und lässt alle anderen Anschlusspins des Arduinos unberührt. Es stellt zusätzlich zwei serielle Anschlüsse in Form des standardisierten Grove-Steckplatzes bereit.\n\nAlle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf dem offiziellen Wiki (bisher nur in englischer Sprache) von Seeed Studio zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen durch die Eingabe der genauen Komponentenbezeichnung entsprechende Projektbeispiele und Tutorials.\n\n\n\n<!-- currently no valid example available...\n## Beispiel\n\nschau dir das Minimal-Beispiel an:\n\n```c++:public/mks/parts/mks-SeeedStudio-SD_Card_shield_V4.0/examples/SD_Card_shield_V4.0_minimal/SD_Card_shield_V4.0_minimal.ino\n// look in the linked file.\n```\n-->\n\n<!-- infolist -->\n\n\n\n## Wichtige Links für die ersten Schritte:\n\n- [Seeed Studio Wiki](http://wiki.seeedstudio.com/SD_Card_shield_V4.0/) [- SD-Karten-Shield](http://wiki.seeedstudio.com/SD_Card_shield_V4.0/)\n\n## Weiterführende Hintergrundinformationen:\n\n- [SD-Karte - Wikipedia Artikel](https://de.wikipedia.org/wiki/SD-Karte)\n- [I2C - Wikipedia Artikel](https://de.wikipedia.org/wiki/I%C2%B2C)\n- [SPI - Wikipedia Artikel](https://de.wikipedia.org/wiki/Serial_Peripheral_Interface)\n- [UART - Wikipedia Artikel](https://de.wikipedia.org/wiki/Universal_Asynchronous_Receiver_Transmitter)\n- [GitHub-Repository: SD-Karten-Shield](https://github.com/MakeYourSchool/73-SD-Karten-Shield)\n\n';
const __vite_glob_3_59 = /* @__PURE__ */ Object.freeze(/* @__PURE__ */ Object.defineProperty({
  __proto__: null,
  default: readme$f
}, Symbol.toStringTag, { value: "Module" }));
const readme$e = '---\ntitle: "Ethernet Shield"\ndate: "2018-10-01T15:04:12.000Z"\ntags: \n  - "shield"\ncoverImage: "69_ethernet_shield.png"\nmaterial_number: "69"\nmaterial_type: "shield"\nmaterial_short_descr: "Seeed Studio W5500 Ethernet Shield v1.0"\nmanufacture: "Seeed Studio"\nmanufacture_url: "https://www.seeedstudio.com/"\nrepo_name: "mks-SeeedStudio-W5500_Ethernet_Shield_v1.0"\nproduct_url: "http://wiki.seeedstudio.com/W5500_Ethernet_Shield_v1.0/"\nclone_url: "https://github.com/Make-Your-School/mks-SeeedStudio-W5500_Ethernet_Shield_v1.0.git"\nrepo_prefix: "mks"\nrepo_part: "W5500_Ethernet_Shield_v1.0"\nembedded_example_file: "examples/W5500_Ethernet_Shield_v1.0_minimal/W5500_Ethernet_Shield_v1.0_minimal.ino"\n---\n\n\n# Ethernet Shield\n\n![Ethernet Shield](./69_ethernet_shield.png)\n\n## Beschreibung\nDas Ethernet Shield ist eine Erweiterungsplatine für Arduino-ähnliche Mikrocontroller. Diese Erweiterungsplatinen werden im Allgemeinen als „Shield“ bezeichnet und werden einfach auf den entsprechenden Controller oder Einplatinencomputer gesteckt. Diese vereinfachen das Anschließen von speziellen Komponenten enorm.\n\nDiese spezielle Ausführung erweitert einen Arduino um einen Ethernet-Anschluss. Dadurch kann der Mikrocontroller in ein LAN-Netzwerk eingebunden werden und damit auch beispielsweise Sensordaten ins Internet streamen. Dieses Modul ist ebenfalls der Grundstein für jedes Internet-of-Things-Projekt.\n\nAlle weiteren Hintergrundinformationen sowie ein Beispielaufbau und alle notwendigen Programmbibliotheken sind auf dem offiziellen Wiki (bisher nur in englischer Sprache) von Seeed Studio zusammengefasst. Zusätzlich findet man über alle gängigen Suchmaschinen durch die Eingabe der genauen Komponentenbezeichnung entsprechende Projektbeispiele und Tutorials.\n\n \n\n\n\n<!-- currently no valid example available...\n## Beispiel\n\nschau dir das Minimal-Beispiel an:\n\n```c++:public/mks/parts/mks-SeeedStudio-W5500_Ethernet_Shield_v1.0/examples/W5500_Ethernet_Shield_v1.0_minimal/W5500_Ethernet_Shield_v1.0_minimal.ino\n// look in the linked file.\n```\n-->\n\n<!-- infolist -->\n\n\n\n## Wichtige Links für die ersten Schritte:\n\n- [Seeed Studio Wi](http://wiki.seeedstudio.com/W5500_Ethernet_Shield_v1.0/)[ki - Ethernet Shield](http://wiki.seeedstudio.com/W5500_Ethernet_Shield_v1.0/)\n- [Adafruit - Arduino Ethernet and SD card - Overview](https://learn.adafruit.com/arduino-ethernet-sd-card)\n\n## Weiterführende Hintergrundinformationen:\n\n- [Ethernet - Wikipedia Artikel](https://de.wikipedia.org/wiki/Ethernet)\n- [Internet-of-things - Wikipedia Artikel](https://de.wikipedia.org/wiki/Internet_der_Dinge)\n- [GitHub-Repository: Ethernet Shield](https://github.com/MakeYourSchool/69-Ethernet-Shield)\n\n';
